"""계획서 6.1 PoC 고정 데이터. 테스트마다 새로 만든다 (딕셔너리 공유 금지)."""
from shop import ShopGraph
C=[("C01","여",23),("C02","여",25),("C03","여",27),("C04","남",24),("C05","여",34),("C06","남",15)]
P=[("P01","오버핏 티셔츠","상의","캐주얼",29000,{"블랙":5,"화이트":5,"그레이":5,"네이비":5}),("P02","와이드 슬랙스","하의","미니멀",39000,{"블랙":3,"베이지":3}),("P03","크롭 가디건","상의","미니멀",45000,{"아이보리":2,"네이비":0}),("P04","카고 팬츠","하의","스트릿",49000,{"카키":4,"블랙":4}),("P05","후드 집업","아우터","스트릿",59000,{"그레이":0,"블랙":0})]
T=[("C01","P01","블랙","2026-09-01"),("C01","P01","화이트","2026-09-08"),("C01","P01","그레이","2026-09-15"),("C01","P01","네이비","2026-10-01"),("C01","P02","블랙","2026-09-03"),("C02","P02","블랙","2026-09-05"),("C02","P02","베이지","2026-09-20"),("C02","P03","아이보리","2026-09-10"),("C03","P03","아이보리","2026-09-12"),("C03","P05","그레이","2026-09-18"),("C04","P04","카키","2026-09-22"),("C04","P05","블랙","2026-09-25"),("C04","P01","블랙","2026-10-02")]
def poc_data():
    return ([{"id":i,"name":f"고객{n+1}","gender":g,"age":a} for n,(i,g,a) in enumerate(C)],
            [{"id":i,"name":nm,"kind":k,"style":st,"price":pr,"stock":dict(s)} for i,nm,k,st,pr,s in P],
            [{"id":f"T{n+1:03d}","customer_id":c,"product_id":p,"color":col,"qty":1,"date":d} for n,(c,p,col,d) in enumerate(T)])
def make_poc(): return ShopGraph(*poc_data())
